CREATE TABLE [dbo].[cstoTarifa](	  [provedor_id] SMALLINT NOT NULL	, [tipoLlamada_id] SMALLINT NOT NULL	, [minutoUno] DECIMAL(15,3) NOT NULL DEFAULT(0)	, [minutoAdicional] DECIMAL(15,3) NOT NULL DEFAULT(0)	, CONSTRAINT [PK_cstoTarifa] PRIMARY KEY ([provedor_id] ASC, [tipoLlamada_id] ASC))ALTER TABLE [dbo].[cstoTarifa] WITH CHECK ADD CONSTRAINT [FK_cstoTarifa_cstoProvedor] FOREIGN KEY([provedor_id]) REFERENCES [dbo].[cstoProvedor] ([provedor_id])ALTER TABLE [dbo].[cstoTarifa] CHECK CONSTRAINT [FK_cstoTarifa_cstoProvedor]